* { box-sizing: border-box; }

body {
     margin: 0;
     min-height: 100vh;
     display: flex;
     flex-wrap: wrap;
     gap: 20px;
     align-items: center;
     justify-content: center;
     font-family: Georgia, "Times New Roman", serif;
     background: #f2f2f2;
     padding: 24px;
}

.dong-ho {
     display: flex;
     align-items: center;
     background: #000000;
     padding: 10px 14px;
     border-radius: 8px;
     box-shadow: 0 10px 24px rgba(0, 0, 0, 0.25);
}

.dong-ho img {
     height: 52px;
     display: block;
}

.chao {
     background: #ffffff;
     border-radius: 8px;
     padding: 12px 26px;
     color: #c62828;
     font-size: 22px;
     font-style: italic;
     box-shadow: 0 8px 20px rgba(0, 0, 0, 0.1);
}

const THU_MUC_ANH = "assets/";
const khungDongHo = document.getElementById("dong-ho");
const khungLoiChao = document.getElementById("loi-chao");

const anhSo = (chuSo) => `<img src="${THU_MUC_ANH}0${chuSo}.gif" alt="${chuSo}">`;
const anhHaiCham = () => `<img src="${THU_MUC_ANH}haicham.gif" alt=":">`;

function capAnhHaiChuSo(n) {
     const hangChuc = Math.floor(n / 10);
     const hangDonVi = n % 10;
     return anhSo(hangChuc) + anhSo(hangDonVi);
}

function layLoiChao(gio) {
     if (gio < 12) return "Chào buổi sáng!";
     if (gio < 18) return "Chào buổi chiều!";
     return "Chào buổi tối!";
}

function capNhatDongHo() {
     const hienTai = new Date();

    const gio = hienTai.getHours();
    const phut = hienTai.getMinutes();
    const giay = hienTai.getSeconds();

    khungDongHo.innerHTML =
      capAnhHaiChuSo(gio) + anhHaiCham() +
      capAnhHaiChuSo(phut) + anhHaiCham() +
      capAnhHaiChuSo(giay);

    khungLoiChao.textContent = layLoiChao(gio);
}

capNhatDongHo();
setInterval(capNhatDongHo, 1000);
